const tags=['暮らし','衣類・バッグ','本・あそび','防災用品'];let opened=null;
const active=p=>!p.sold&&p.reservation&&p.reservation.until>Date.now();
function expire(){let changed=false;state.products.forEach(p=>{if(p.reservation&&p.reservation.until<=Date.now()){delete p.reservation;changed=true}});if(changed)save();return changed}
function reserve(id){expire();let p=state.products.find(p=>p.id===id);if(!p||p.sold||active(p)||p.seller===uid)return false;p.reservation={by:uid,until:Date.now()+1800000};save();return true}
function complete(id,buyer,notify){expire();let p=state.products.find(p=>p.id===id);if(!p||p.sold||!user(buyer)||p.seller===buyer||(active(p)&&p.reservation.by!==buyer))return false;p.sold=true;p.buyer=buyer;delete p.reservation;let u=user(buyer);state.notices.unshift({to:p.seller,buyer,notify,item:id,text:notify?`${u.room}号室の${u.name}さんが商品 #${id} を交換しました。`:`商品 #${id} が会場で交換されました。`,time:new Date().toLocaleString('ja-JP'),read:false});save();return true}
function due(p){return new Date(p.reservation.until).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'})}function left(p){return Math.max(0,Math.ceil((p.reservation.until-Date.now())/60000))}
seller=function(u){return `${avatar(u)}<span>${esc(u.name)} さん</span>`};
market=function(){expire();$('#main').innerHTML=`<div class="marketbar"><div class="filters">${['すべて',...tags].map(t=>`<button class="pill ${filter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div><span class="muted">残高 ${me().points} pt</span></div><div class="grid" id="products"></div><p class="muted" style="margin-top:28px">交換・ポイントの調整は現地のスタッフ受付で。</p>`;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;market()});cards()};
cards=function(){let ps=state.products.filter(p=>filter==='すべて'||p.category===filter);$('#products').innerHTML=ps.map(p=>`<button class="card" data-item="${p.id}" aria-label="商品 #${p.id} を見る"><div class="photo"><img src="${esc(p.image)}" alt="${esc(p.category)}の商品 #${p.id}" loading="lazy"><span class="tag">${esc(p.category)}</span>${p.sold?'<div class="sold">交換済み</div>':active(p)?`<span class="reservebadge">${p.reservation.by===uid?'あなたが予約中':'予約中'} · あと${left(p)}分</span>`:''}</div><div class="cardbody"><div class="seller">${seller(user(p.seller))}</div></div></button>`).join('')||'<p class="muted">まだありません。</p>';document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>detail(+b.dataset.item))};
detail=function(id){expire();opened=id;const p=state.products.find(p=>p.id===id);$('#detail').innerHTML=`<button class="close" aria-label="閉じる">×</button><img class="modalphoto" src="${esc(p.image)}" alt="商品 #${id}"><div class="modalbody"><span class="muted">${esc(p.category)} · #${id}</span><div class="seller">${seller(user(p.seller))}</div><div style="margin-top:24px">${p.sold?'<p>交換済みです</p>':active(p)?p.reservation.by===uid?`<p><b>${due(p)} までにスタッフ受付へ</b><br><span class="muted">あと${left(p)}分。期限を過ぎると自動解除されます。</span></p><button class="secondary" id="cancel">予約を取り消す</button>`:'<p>ほかの方が予約中です</p>':p.seller===uid?'<p class="muted">あなたの出品です</p>':'<button class="primary" id="reserve">30分以内に取りに行く</button><p class="muted">30分間取り置きします。交換とポイントの調整は現地で。</p>'}</div></div>`;$('#detail .close').onclick=()=>$('#detail').close();if($('#reserve'))$('#reserve').onclick=()=>{reserve(id);detail(id);market()};if($('#cancel'))$('#cancel').onclick=()=>{if(active(p)&&p.reservation.by===uid){delete p.reservation;save()}detail(id);market()};if(!$('#detail').open)$('#detail').showModal()};
function tagOptions(v){return tags.map(t=>`<option ${t===v?'selected':''}>${t}</option>`).join('')}
staff=function(){expire();$('#main').innerHTML=`<h2>スタッフ受付</h2><div class="forms"><form class="panel" id="register"><h3>写真を登録</h3><label class="field">写真<input name="photo" type="file" accept="image/*" required></label><label class="field">出品者<select name="seller">${options()}</select></label><label class="field">分類タグ<select name="category">${tagOptions()}</select></label><label class="check"><input type="checkbox" required>現物・安全性を確認し、交換可能と判断しました</label><button class="primary">登録する</button></form><form class="panel" id="points"><h3>ポイントを手入力</h3><label class="field">住民<select name="person">${options()}</select></label><label class="field">変更後の残高<input name="amount" type="number" min="0" max="999999" step="1" required></label><button class="primary">残高を更新</button><p class="muted">予約・交換完了では自動減算しません。</p></form></div><div class="panel"><h3>商品と現地交換</h3>${state.products.map(p=>`<article class="staffitem"><img src="${esc(p.image)}" alt="商品 #${p.id}"><div><b>#${p.id}</b> · ${esc(user(p.seller).name)} さん<label class="field">分類タグ<select data-classify="${p.id}">${tagOptions(p.category)}</select></label><p class="muted">${p.sold?'交換済み':active(p)?`${esc(user(p.reservation.by).name)} さん予約中 · ${due(p)}まで`:'予約なし'}</p>${p.sold?'':`<form data-complete="${p.id}"><label class="field">受け取る住民<select name="buyer">${state.users.filter(u=>u.id!==p.seller).map(u=>`<option value="${u.id}" ${active(p)&&p.reservation.by===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="notify">出品者への氏名・部屋番号の通知に本人が同意</label><button class="secondary">現地で交換済みにする</button></form>`}</div></article>`).join('')}</div><div class="panel"><h3>顔写真の掲載同意</h3>${state.users.map(u=>`<label class="check"><input type="checkbox" data-consent="${u.id}" ${u.consent?'checked':''}>${esc(u.name)} さん · 本人の同意を確認済み</label>`).join('')}</div><p class="muted">電池等の回収判断は現地スタッフが行い、回収品は商品登録しないでください。</p>`;
let f=$('#points'),v=k=>f.elements.namedItem(k);v('person').onchange=()=>v('amount').value=user(+v('person').value).points;v('person').onchange();f.onsubmit=e=>{e.preventDefault();let amount=+v('amount').value;if(!Number.isSafeInteger(amount)||amount<0||amount>999999)return;user(+v('person').value).points=amount;save();toast('残高を更新しました')};$('#register').onsubmit=async e=>{e.preventDefault();let f=e.target,v=k=>f.elements.namedItem(k);try{let image=await readFile(v('photo').files[0]);state.products.unshift({id:Date.now(),seller:+v('seller').value,category:v('category').value,image});save();staff();toast('登録しました')}catch(e){toast(e.message)}};document.querySelectorAll('[data-classify]').forEach(s=>s.onchange=()=>{state.products.find(p=>p.id===+s.dataset.classify).category=s.value;save()});document.querySelectorAll('[data-consent]').forEach(c=>c.onchange=()=>{user(+c.dataset.consent).consent=c.checked;save()});document.querySelectorAll('[data-complete]').forEach(f=>f.onsubmit=e=>{e.preventDefault();let ok=complete(+f.dataset.complete,+f.elements.namedItem('buyer').value,f.elements.namedItem('notify').checked);staff();toast(ok?'交換済み。ポイントは手入力で調整してください。':'予約者と予約期限を確認してください')})};
notices=function(){let ns=state.notices.filter(n=>n.to===uid);$('#main').innerHTML=`<h2>お知らせ</h2><div class="panel">${ns.map(n=>`<div class="notice"><small class="muted">${esc(n.time)}</small><p>${esc(n.text)}</p></div>`).join('')||'<p class="muted">まだありません。</p>'}</div>`;ns.forEach(n=>n.read=true);save();$('#badge').textContent=''};
$('#user').onchange=e=>{uid=+e.target.value;$('#detail').close();opened=null;render()};$('#detail').addEventListener('close',()=>opened=null);setInterval(()=>{expire();if(page==='market')market();if(opened)detail(opened)},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){expire();render();if(opened)detail(opened)}});window.addEventListener('storage',e=>{if(e.key==='meguru-v1'&&e.newValue){try{state=JSON.parse(e.newValue);render();if(opened)detail(opened)}catch{}}});render();
